        sse_encode_i_32(0, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_String(rootPath, serializer);
        sse_encode_opt_box_autoadd_u_32(itemLimit, serializer);
        sse_encode_opt_box_autoadd_u_32(entryLimit, serializer);
      case ScanEvent_Progress(
        scanId: final scanId,
        visitedEntries: final visitedEntries,
        acceptedItems: final acceptedItems,
        issueCount: final issueCount,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_u_64(visitedEntries, serializer);
        sse_encode_u_64(acceptedItems, serializer);
        sse_encode_u_64(issueCount, serializer);
      case ScanEvent_Finalizing(
        scanId: final scanId,
        validatedItems: final validatedItems,
        totalItems: final totalItems,
        visitedEntries: final visitedEntries,
        acceptedItems: final acceptedItems,
        issueCount: final issueCount,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_u_64(validatedItems, serializer);
        sse_encode_u_64(totalItems, serializer);
        sse_encode_u_64(visitedEntries, serializer);
        sse_encode_u_64(acceptedItems, serializer);
        sse_encode_u_64(issueCount, serializer);
      case ScanEvent_AssetDiscovered(scanId: final scanId, asset: final asset):
        sse_encode_i_32(3, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_box_asset_location_view(asset, serializer);
      case ScanEvent_Issue(scanId: final scanId, issue: final issue):
        sse_encode_i_32(4, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_box_autoadd_scan_issue(issue, serializer);
      case ScanEvent_Completed(
        scanId: final scanId,
        rootId: final rootId,
        assetCount: final assetCount,
        issueCount: final issueCount,
        catalogPath: final catalogPath,
        wasLimited: final wasLimited,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_String(rootId, serializer);
        sse_encode_u_64(assetCount, serializer);
        sse_encode_u_64(issueCount, serializer);
        sse_encode_String(catalogPath, serializer);
        sse_encode_bool(wasLimited, serializer);
      case ScanEvent_Cancelled(
        scanId: final scanId,
        acceptedItems: final acceptedItems,
        issueCount: final issueCount,
      ):
        sse_encode_i_32(6, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_u_64(acceptedItems, serializer);
        sse_encode_u_64(issueCount, serializer);
      case ScanEvent_Paused(
        scanId: final scanId,
        visitedEntries: final visitedEntries,
        acceptedItems: final acceptedItems,
        issueCount: final issueCount,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_u_64(visitedEntries, serializer);
        sse_encode_u_64(acceptedItems, serializer);
        sse_encode_u_64(issueCount, serializer);
      case ScanEvent_Stale(
        scanId: final scanId,
        acceptedItems: final acceptedItems,
        issueCount: final issueCount,
      ):
        sse_encode_i_32(8, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_u_64(acceptedItems, serializer);
        sse_encode_u_64(issueCount, serializer);
      case ScanEvent_Failed(
        scanId: final scanId,
        code: final code,
        message: final message,
      ):
        sse_encode_i_32(9, serializer);
        sse_encode_String(scanId, serializer);
        sse_encode_String(code, serializer);
        sse_encode_String(message, serializer);
    }
  }

  @protected
  void sse_encode_scan_issue(ScanIssue self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_String(self.path, serializer);
    sse_encode_String(self.code, serializer);
    sse_encode_String(self.message, serializer);
  }

  @protected
  void sse_encode_scan_request(ScanRequest self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.scanId, serializer);
    sse_encode_String(self.rootPath, serializer);
    sse_encode_opt_box_autoadd_u_32(self.maxItems, serializer);
    sse_encode_opt_box_autoadd_u_32(self.maxEntries, serializer);
    sse_encode_u_32(self.previewEdge, serializer);
  }

  @protected
  void sse_encode_storage_settings_update(
    StorageSettingsUpdate self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_String(self.catalogDirectory, serializer);
    sse_encode_opt_String(self.previewCacheDirectory, serializer);
    sse_encode_u_64(self.previewBudgetBytes, serializer);
  }

  @protected
  void sse_encode_storage_status(StorageStatus self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.settingsPath, serializer);
    sse_encode_String(self.activeCatalogPath, serializer);
    sse_encode_String(self.activePreviewRoot, serializer);
    sse_encode_String(self.configuredCatalogPath, serializer);
    sse_encode_String(self.configuredPreviewRoot, serializer);
    sse_encode_String(self.configuredCatalogDisplayPath, serializer);
    sse_encode_String(self.configuredPreviewDisplayPath, serializer);
    sse_encode_u_64(self.previewBudgetBytes, serializer);
    sse_encode_u_64(self.previewUsedBytes, serializer);
    sse_encode_u_64(self.catalogUsedBytes, serializer);
    sse_encode_bool(self.requiresRestart, serializer);
    sse_encode_list_retired_preview_root_view(
      self.retiredPreviewRoots,
      serializer,
    );
  }

  @protected
  void sse_encode_u_16(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint16(self);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
